                        longflag == 0 ? (unsigned long)va_arg(
                                            va, unsigned int) :
                                        va_arg(va, unsigned long),
                        16, (ch == 'X'), 1, bf, zero_pad);
                    _puts(bf, len, &b);
                    longflag = 0;
                    break;

                case 'c':
                    _putc((char)(va_arg(va, int)), &b);
                    break;

                case 's':
                    ptr = va_arg(va, char *);
                    _puts(ptr, mini_strlen(ptr), &b);
                    break;

                default:
                    _putc(ch, &b);
                    break;
            }
        }
    }
end:
    return b.pbuffer - b.buffer;
}

int vprintk(const char *fmt, va_list _va)
{
    va_list va;
    va_copy(va, _va);

    int ret;
    char buff[256];

    ret = mini_vsnprintf(buff, 256, fmt, va);

    buff[ret] = '\0';

    disable_preempt();
    port_write(buff);
    for (int i = 0; i < ret; ++i) {
        if (buff[i] == '\n') {
            current_running->cursor_y++;
        } else if (buff[i] == '\r') {
            current_running->cursor_x = 1;
        } else {
            current_running->cursor_x++;
        }
    }
    enable_preempt();

    return ret;
}

int printk(const char *fmt, ...)
{
    int ret = 0;
    va_list va;

    va_start(va, fmt);
    ret = vprintk(fmt, va);
    va_end(va);

    return ret;
}
