void do_scheduler(void)
{
    pcb_t *prev_running = current_running;

    /* the task that gave up the CPU voluntarily is still runnable,
     * so put it back to the tail of the ready queue (round-robin).
     * pid0 is the idle task of the kernel and never joins the queue. */
    if (prev_running != &pid0_pcb && prev_running->status == TASK_RUNNING) {
        prev_running->status = TASK_READY;
        list_add_tail(&prev_running->list, &ready_queue);
    }

    /* pick the task at the head of the ready queue, fall back to the
     * idle task (pid0) when nothing else is runnable */
    if (list_empty(&ready_queue)) {
        current_running = &pid0_pcb;
    } else {
        list_node_t *next_node = ready_queue.next;
        list_del(next_node);
        current_running = list_entry(next_node, pcb_t, list);
    }
    current_running->status = TASK_RUNNING;

    /* the screen cursor belongs to the task that owns the CPU */
    screen_cursor_x = current_running->cursor_x;
    screen_cursor_y = current_running->cursor_y;

    /* switch to the new task, this must be the last thing we do */
    switch_to(prev_running, current_running);
}

// block the pcb task into the block queue
void do_block(list_node_t *pcb_node, list_head *queue)
{
    pcb_t *pcb_block = list_entry(pcb_node, pcb_t, list);

    /* leave whatever queue we are on and wait on `queue` */
    list_del(pcb_node);
    list_add_tail(pcb_node, queue);
    pcb_block->status = TASK_BLOCKED;
}

// unblock the `pcb` from the block queue
void do_unblock(list_node_t *pcb_node)
{
    pcb_t *pcb_unblock = list_entry(pcb_node, pcb_t, list);

    /* take it off the block queue and make it runnable again */
    list_del(pcb_node);
    list_add_tail(pcb_node, &ready_queue);
    pcb_unblock->status = TASK_READY;
}

