void do_mutex_lock_acquire(mutex_lock_t *lock)
{
    /* wait until the lock is free; recheck after every wakeup because
     * another task may have grabbed the lock in the meantime */
    while (lock->lock.status == LOCKED) {
        do_block(&current_running->list, &(lock->block_queue));
        do_scheduler();
    }
    lock->lock.status = LOCKED;
}

void do_mutex_lock_release(mutex_lock_t *lock)
{
    lock->lock.status = UNLOCKED;

    /* wake up every waiter, they will compete for the lock again */
    while (!list_empty(&(lock->block_queue))) {
        do_unblock(lock->block_queue.next);
    }
}

