/*
 * Host-side unit test for the Project 2 Part 1 cooperative scheduler and mutex.
 *
 * kernel/sched/sched.c and kernel/locking/lock.c are compiled for the host with
 * stubs standing in for the assembly context switch and the screen driver, so the
 * queue bookkeeping can be exercised without a RISC-V board.
 */
#include <os/sched.h>
#include <os/lock.h>

/* --- stubs for the parts of the kernel we do not want to drag in --- */
int screen_cursor_x;
int screen_cursor_y;

/* the last (prev, next) pair handed to the assembly context switch */
pcb_t *last_switch_prev;
pcb_t *last_switch_next;
int switch_count;

void switch_to(pcb_t *prev, pcb_t *next)
{
    last_switch_prev = prev;
    last_switch_next = next;
    switch_count++;
}

void port_write_ch(char ch) { (void)ch; }
void port_write(char *buf) { (void)buf; }
int printk(const char *fmt, ...) { (void)fmt; return 0; }
void vt100_move_cursor(int x, int y) { (void)x; (void)y; }
void disable_preempt(void) {}
void enable_preempt(void) {}

/* --- tiny test harness --- */
extern int host_printf(const char *fmt, ...);
static int failures;

#define CHECK(cond)                                                       \
    do {                                                                  \
        if (!(cond)) {                                                    \
            failures++;                                                   \
            host_printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);   \
        }                                                                 \
    } while (0)

static int queue_length(list_head *head)
{
    int n = 0;
    for (list_node_t *p = head->next; p != head; p = p->next) n++;
    return n;
}

static int queue_contains(list_head *head, list_node_t *node)
{
    for (list_node_t *p = head->next; p != head; p = p->next)
        if (p == node) return 1;
    return 0;
}

static void reset_world(int ntasks)
{
    init_list_head(&ready_queue);
    for (int i = 0; i < ntasks; i++) {
        pcb[i].pid = i + 1;
        pcb[i].status = TASK_READY;
        pcb[i].cursor_x = 1;
        pcb[i].cursor_y = 1;
        init_list_head(&pcb[i].list);
        list_del(&pcb[i].list);
        list_add_tail(&pcb[i].list, &ready_queue);
    }
    pid0_pcb.status = TASK_RUNNING;
    pid0_pcb.cursor_x = 1;
    pid0_pcb.cursor_y = 1;
    current_running = &pid0_pcb;
    switch_count = 0;
}

/* round robin: three tasks must be visited in FIFO order, over and over */
static void test_round_robin(void)
{
    reset_world(3);

    do_scheduler();
    CHECK(current_running == &pcb[0]);
    CHECK(last_switch_prev == &pid0_pcb);
    CHECK(last_switch_next == &pcb[0]);
    CHECK(current_running->status == TASK_RUNNING);
    /* pid0 is the idle task, it must never enter the ready queue */
    CHECK(!queue_contains(&ready_queue, &pid0_pcb.list));
    CHECK(queue_length(&ready_queue) == 2);

    do_scheduler();
    CHECK(current_running == &pcb[1]);
    CHECK(pcb[0].status == TASK_READY);
    CHECK(queue_contains(&ready_queue, &pcb[0].list));

    do_scheduler();
    CHECK(current_running == &pcb[2]);

    /* wrap around to the first task again */
    do_scheduler();
    CHECK(current_running == &pcb[0]);
    do_scheduler();
    CHECK(current_running == &pcb[1]);
}

/* a single runnable task keeps running; no runnable task falls back to pid0 */
static void test_idle_fallback(void)
{
    reset_world(1);

    do_scheduler();
    CHECK(current_running == &pcb[0]);
    do_scheduler();
    CHECK(current_running == &pcb[0]);

    /* block the only task: the scheduler must fall back to pid0 */
    LIST_HEAD(wait_queue);
    do_block(&pcb[0].list, &wait_queue);
    CHECK(pcb[0].status == TASK_BLOCKED);
    CHECK(queue_contains(&wait_queue, &pcb[0].list));
    CHECK(list_empty(&ready_queue));

    do_scheduler();
    CHECK(current_running == &pid0_pcb);

    /* a blocked task must not be pushed back to the ready queue */
    do_scheduler();
    CHECK(current_running == &pid0_pcb);
    CHECK(list_empty(&ready_queue));

    do_unblock(&pcb[0].list);
    CHECK(pcb[0].status == TASK_READY);
    CHECK(list_empty(&wait_queue));
    CHECK(queue_contains(&ready_queue, &pcb[0].list));

    do_scheduler();
    CHECK(current_running == &pcb[0]);
}

/* the cursor of the incoming task becomes the screen cursor */
static void test_cursor_follows_task(void)
{
    reset_world(2);
    pcb[0].cursor_x = 7;
    pcb[0].cursor_y = 9;
    pcb[1].cursor_x = 11;
    pcb[1].cursor_y = 13;

    do_scheduler();
    CHECK(screen_cursor_x == 7 && screen_cursor_y == 9);
    do_scheduler();
    CHECK(screen_cursor_x == 11 && screen_cursor_y == 13);
}

/* mutex: the second acquirer blocks, and release hands the lock over */
static void test_mutex(void)
{
    reset_world(2);
    mutex_lock_t lock;
    do_mutex_lock_init(&lock);

    do_scheduler();                 /* pcb[0] runs */
    CHECK(current_running == &pcb[0]);
    do_mutex_lock_acquire(&lock);   /* uncontended, must not block */
    CHECK(lock.lock.status == LOCKED);
    CHECK(current_running == &pcb[0]);
    CHECK(list_empty(&lock.block_queue));

    do_scheduler();                 /* pcb[1] runs */
    CHECK(current_running == &pcb[1]);
    /* contended: pcb[1] blocks, and the scheduler inside acquire hands the
     * CPU back to pcb[0], which then releases the lock for us */
    do_mutex_lock_acquire(&lock);
    /* after the (stubbed) switch, pcb[1] is on the lock's block queue */
    CHECK(pcb[1].status == TASK_BLOCKED);
    CHECK(queue_contains(&lock.block_queue, &pcb[1].list));

