void do_mutex_lock_acquire(mutex_lock_t *lock)
{
    /* only kernel tasks use this lock, and they can be resumed in the
     * middle of a function, so it is safe to loop here: after every
     * wakeup we recheck whether the lock is really free */
    while (lock->lock.status == LOCKED) {
