    ptr_t ret = ROUND(memCurr, PAGE_SIZE) + numPage * PAGE_SIZE;
    memCurr = ret;
    return ret;
}

void* kmalloc(size_t size)
{
    // align 4
    ptr_t ret = ROUND(memCurr, 4) + size;
    memCurr = ret;
    return (void*)ret;
}    EXCC_COUNT
};

