static char heap[65536];
static size_t heap_used;
void *kmalloc(size_t size)
{
    void *ret = &heap[heap_used];
    heap_used = (heap_used + size + 7) & ~(size_t)7;
    return ret;
}
ptr_t allocPage(int numPage) { (void)numPage; return 0; }

/* --- tiny test harness --- */
extern int host_printf(const char *fmt, ...);
static int failures;

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            failures++;                                                 \
            host_printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                               \
    } while (0)

static int queue_length(list_head *head)
{
    int n = 0;
    for (list_node_t *p = head->next; p != head; p = p->next) n++;
    return n;
}

static int queue_contains(list_head *head, list_node_t *node)
{
    for (list_node_t *p = head->next; p != head; p = p->next)
        if (p == node) return 1;
    return 0;
}

/* one scheduling round is timer_interval ticks long */
static void reset_world(int ntasks)
{
    fake_ticks = 1000;
    time_base = 10000;
    timer_interval = time_base / 200; /* 50 */

    init_list_head(&ready_queue);
    init_list_head(&sleep_queue);
    init_list_head(&timer_queue);
    for (int i = 0; i < ntasks; i++) {
        pcb[i].pid = i + 1;
        pcb[i].status = TASK_READY;
        pcb[i].priority = 0;
        pcb[i].ready_tick = fake_ticks;
        pcb[i].preempt_count = 0;
        pcb[i].cursor_x = 1;
        pcb[i].cursor_y = 1;
        list_add_tail(&pcb[i].list, &ready_queue);
    }
    pid0_pcb.status = TASK_RUNNING;
    pid0_pcb.cursor_x = 1;
    pid0_pcb.cursor_y = 1;
    current_running = &pid0_pcb;
    yield_count = 0;
    on_yield = NULL;
    preempt_depth = 0;
}

/* equal priorities degrade to first-come-first-served */
static void test_priority_order(void)
{
    reset_world(3);
    pcb[0].ready_tick = fake_ticks - 3 * timer_interval;
    pcb[1].ready_tick = fake_ticks - 1 * timer_interval;
    pcb[2].ready_tick = fake_ticks - 2 * timer_interval;
    CHECK(max_priority_node() == &pcb[0].list); /* waited longest */

    /* a higher static priority wins when the wait is the same */
    reset_world(3);
    pcb[0].priority = 10;
    pcb[1].priority = 104;
    pcb[2].priority = 56;
    CHECK(max_priority_node() == &pcb[1].list);

    /* ... but waiting long enough beats a higher static priority */
    pcb[0].ready_tick = fake_ticks - 100 * timer_interval;
    CHECK(max_priority_node() == &pcb[0].list);

    /* an empty ready queue has no candidate */
    init_list_head(&ready_queue);
    CHECK(max_priority_node() == NULL);
}

static void test_scheduler(void)
{
    reset_world(3);
    pcb[0].priority = 10;
    pcb[1].priority = 104;
    pcb[2].priority = 56;

    scheduler();
    CHECK(current_running == &pcb[1]); /* highest priority first */
    CHECK(current_running->status == TASK_RUNNING);
    CHECK(!queue_contains(&ready_queue, &pcb[1].list));
    /* pid0 is the idle task and must stay out of the ready queue */
    CHECK(!queue_contains(&ready_queue, &pid0_pcb.list));
    CHECK(queue_length(&ready_queue) == 2);

    /* the outgoing task goes back with a fresh timestamp so that its wait
     * time starts counting from now */
    fake_ticks += timer_interval;
    scheduler();
    CHECK(current_running == &pcb[2]);
    CHECK(pcb[1].status == TASK_READY);
    CHECK(pcb[1].ready_tick == fake_ticks - timer_interval);

    /* a blocked task must not be put back on the ready queue */
    do_block(&current_running->list, &sleep_queue);
    CHECK(current_running->status == TASK_BLOCKED);
    scheduler();
    CHECK(!queue_contains(&ready_queue, &pcb[2].list));
    CHECK(queue_contains(&sleep_queue, &pcb[2].list));

    /* nothing runnable falls back to the idle task */
    init_list_head(&ready_queue);
    current_running->status = TASK_BLOCKED;
    scheduler();
    CHECK(current_running == &pid0_pcb);

    /* the incoming task's cursor becomes the screen cursor */
    reset_world(1);
    pcb[0].cursor_x = 17;
    pcb[0].cursor_y = 23;
    scheduler();
    CHECK(screen_cursor_x == 17 && screen_cursor_y == 23);
}

/* do_sleep + timer_check must round-trip a task through the sleep queue */
static int fired;
static void count_fire(void *parameter)
{
    (void)parameter;
    fired++;
}

static void test_timer_check(void)
{
    reset_world(2);
    scheduler();
    CHECK(current_running == &pcb[0]);

    /* nothing has expired yet */
    fired = 0;
    timer_create(count_fire, NULL, fake_ticks + 100);
    CHECK(queue_length(&timer_queue) == 1);
    timer_check();
    CHECK(fired == 0);
    CHECK(queue_length(&timer_queue) == 1);

    /* ... and now it has */
    fake_ticks += 100;
    timer_check();
    CHECK(fired == 1);
    CHECK(queue_length(&timer_queue) == 0);

    /* an expired timer only fires once */
    timer_check();
    CHECK(fired == 1);

    /* do_sleep parks the task and the timer wakes it up again */
    reset_world(2);
    scheduler();
    CHECK(current_running == &pcb[0]);
    do_sleep(1); /* time_base * 1 ticks */
    CHECK(pcb[0].status == TASK_BLOCKED);
    CHECK(queue_contains(&sleep_queue, &pcb[0].list));
    CHECK(current_running == &pcb[1]);
    CHECK(queue_length(&timer_queue) == 1);

    timer_check();
    CHECK(pcb[0].status == TASK_BLOCKED); /* not yet */
    fake_ticks += time_base;
    timer_check();
    CHECK(pcb[0].status == TASK_READY);
    CHECK(queue_contains(&ready_queue, &pcb[0].list));
    CHECK(list_empty(&sleep_queue));
    CHECK(queue_length(&timer_queue) == 0);
}

static mutex_lock_t test_lock;

static void owner_releases_lock(void)
{
    do_mutex_lock_release(&test_lock);
    /* and the scheduler hands the CPU back to us */
    list_del(&pcb[1].list);
    pcb[1].status = TASK_RUNNING;
    current_running = &pcb[1];
}

static void test_mutex(void)
{
    reset_world(2);
    do_mutex_lock_init(&test_lock);

    scheduler();
    CHECK(current_running == &pcb[0]);
    do_mutex_lock_acquire(&test_lock);
    CHECK(test_lock.lock.status == LOCKED);
    CHECK(yield_count == 0); /* uncontended: no yield */

    /* let pcb[1] run into the contended path */
    list_del(&pcb[1].list);
    pcb[1].status = TASK_RUNNING;
    current_running = &pcb[1];
    on_yield = owner_releases_lock;
    do_mutex_lock_acquire(&test_lock);
    CHECK(yield_count == 1);
    CHECK(test_lock.lock.status == LOCKED);
    CHECK(current_running == &pcb[1]);
    CHECK(list_empty(&test_lock.block_queue));

    do_mutex_lock_release(&test_lock);
    CHECK(test_lock.lock.status == UNLOCKED);
}

static void test_binsem(void)
{
    reset_world(2);
    init_system_binsem();

    int id = binsem_get(42);
    CHECK(id >= 0 && id < BINSEM_NUMBER);
    /* the same key always maps to the same semaphore */
    CHECK(binsem_get(42) == id);
    CHECK(binsem_nodes[id].sem == 1);

    scheduler();
    CHECK(current_running == &pcb[0]);
    binsem_op(id, BINSEM_OP_LOCK);
    CHECK(binsem_nodes[id].sem == 0);
    CHECK(current_running == &pcb[0]); /* uncontended: no reschedule */

    /* pcb[1] finds it taken and blocks */
    scheduler();
    CHECK(current_running == &pcb[1]);
    binsem_op(id, BINSEM_OP_LOCK);
    CHECK(pcb[1].status == TASK_BLOCKED);
    CHECK(queue_contains(&binsem_nodes[id].block_queue, &pcb[1].list));
    CHECK(current_running == &pcb[0]);

    /* the owner releases: the semaphore is handed to the waiter, which owns
     * it as soon as it wakes up, so sem stays taken */
    binsem_op(id, BINSEM_OP_UNLOCK);
    CHECK(binsem_nodes[id].sem == 0);
    CHECK(pcb[1].status == TASK_READY || pcb[1].status == TASK_RUNNING);
    CHECK(list_empty(&binsem_nodes[id].block_queue));

    /* releasing with nobody waiting frees the semaphore */
    binsem_op(id, BINSEM_OP_UNLOCK);
    CHECK(binsem_nodes[id].sem == 1);

    /* an out-of-range id is ignored rather than corrupting memory */
    binsem_op(-1, BINSEM_OP_LOCK);
    binsem_op(BINSEM_NUMBER, BINSEM_OP_LOCK);
    CHECK(binsem_nodes[id].sem == 1);

    /* preempt bookkeeping stays balanced */
    CHECK(preempt_depth == 0);
}

static void test_futex(void)
{
    volatile uint64_t val = 1;

    reset_world(3);
    init_system_futex();

    /* the value no longer matches: nothing to wait for */
    scheduler();
    CHECK(current_running == &pcb[0]);
    futex_wait(&val, 0);
    CHECK(pcb[0].status == TASK_RUNNING);
    CHECK(current_running == &pcb[0]);

    /* the value matches: block */
    futex_wait(&val, 1);
    CHECK(pcb[0].status == TASK_BLOCKED);
    CHECK(current_running != &pcb[0]);

    /* a second waiter on the same address joins the same bucket */
    pcb_t *second = current_running;
    futex_wait(&val, 1);
    CHECK(second->status == TASK_BLOCKED);

    /* wake exactly one of them */
    val = 0;
    futex_wakeup(&val, 1);
    int woken = (pcb[0].status != TASK_BLOCKED) + (second->status != TASK_BLOCKED);
    CHECK(woken == 1);

    /* and then the other */
    futex_wakeup(&val, 8);
    CHECK(pcb[0].status != TASK_BLOCKED);
    CHECK(second->status != TASK_BLOCKED);

    /* waking an address nobody waits on is harmless */
    volatile uint64_t other = 7;
    futex_wakeup(&other, 4);

    CHECK(preempt_depth == 0);
}

int run_tests(void)
{
    test_priority_order();
    test_scheduler();
    test_timer_check();
    test_mutex();
    test_binsem();
    test_futex();

    if (failures == 0)
        host_printf("p2b: all scheduler/timer/lock checks passed\n");
    else
        host_printf("p2b: %d check(s) FAILED\n", failures);
    return failures != 0;
}

