/* the idle task of a core never competes for the CPU in the ready queue */
static int is_idle_task(pcb_t *task)
{
    return task == &kernel_pcb[0] || task == &kernel_pcb[1];
}

/*
 * Hand every binary semaphore the task still holds to the next waiter, so
 * that a task dying inside a critical section does not lock up the system.
 */
static void release_binsem(pcb_t *dead)
{
    for (int i = 0; i < dead->binsem_num; i++) {
        binsem_node_t *node = &binsem_nodes[dead->binsem_id[i]];

        if (list_empty(&node->block_queue)) {
            node->sem = 1;
        } else {
            /* the semaphore is handed over, so the woken task owns it */
            list_node_t *waiter = node->block_queue.next;
            pcb_t *new_owner = list_entry(waiter, pcb_t, list);
            if (new_owner->binsem_num < BINSEM_NUMBER) {
                new_owner->binsem_id[new_owner->binsem_num++] = dead->binsem_id[i];
            }
            do_unblock(waiter);
        }
    }
    dead->binsem_num = 0;
}

/* give up everything the task holds and let whoever waits for it continue */
static void release_resources(pcb_t *dead)
{
    release_binsem(dead);

    while (!list_empty(&dead->wait_list)) {
        do_unblock(dead->wait_list.next);
    }

    /* it may still sit on a block queue and have a sleep timer armed */
    list_del(&dead->list);
    list_del(&dead->timer.list);
}

/*
 * The last step of a task's life. A task can not free the kernel stack it
 * is running on, so in AUTO_CLEANUP mode the PCB is handed to core 0's idle
 * task; in ZOMBIE mode do_waitpid() collects it instead.
 */
static void retire_pcb(pcb_t *dead)
{
    if (dead->mode == ENTER_ZOMBIE_ON_EXIT) {
        dead->status = TASK_ZOMBIE;
    } else {
        dead->status = TASK_EXITED;
        freePage(dead->user_stack_base, 1);
        list_add_tail(&dead->list, &kernel_pcb[0].wait_list);
    }
}

void scheduler(void)
{
    pcb_t *prev_running = current_running[cpu_id];

    if (prev_running->status == TASK_KILLED) {
        /* it was killed while running on this core, finish the job now
         * that we are no longer using its stack */
        retire_pcb(prev_running);
    } else if (!is_idle_task(prev_running) && prev_running->status == TASK_RUNNING) {
        /* still runnable: let it compete for the CPU again */
        prev_running->status = TASK_READY;
        prev_running->ready_tick = get_ticks();
        list_add_tail(&prev_running->list, &ready_queue);
    }

    /* pick the ready task with the highest dynamic priority, or go idle */
    list_node_t *next_node = max_priority_node();
    if (next_node == NULL) {
        current_running[cpu_id] = &kernel_pcb[cpu_id];
    } else {
        list_del(next_node);
        current_running[cpu_id] = list_entry(next_node, pcb_t, list);
    }
    current_running[cpu_id]->status = TASK_RUNNING;
    current_running[cpu_id]->cpu_id = cpu_id;

    /* ret_from_exception restores the context of `current_cpu_running` */
    current_cpu_running = current_running[cpu_id];

    /* the screen cursor of this core belongs to the task that owns it */
    screen_cursor_x[cpu_id] = current_running[cpu_id]->cursor_x;
    screen_cursor_y[cpu_id] = current_running[cpu_id]->cursor_y;
}

/* prepare a kernel stack that looks like a task trapped into the kernel */
static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
                           pcb_t *new_pcb, void *arg)
{
    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
    new_pcb->kernel_sp -= sizeof(regs_context_t);

    /* initialization registers: ra, sp, gp, a0, sstatus, sepc, sscratch */
    pt_regs->regs[1] = (reg_t)entry_point;       //ra
    pt_regs->regs[2] = (reg_t)user_stack;        //sp
    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
    pt_regs->regs[10] = (reg_t)arg;              //a0, the task's argument
    pt_regs->sstatus = (reg_t)SR_SPIE;           //SPP = 0, SPIE = 1
    pt_regs->sepc = (reg_t)entry_point;
    pt_regs->sscratch = (reg_t)new_pcb;          //sscratch = tp
}

pid_t do_spawn(task_info_t *task, void* arg, spawn_mode_t mode)
{
    disable_preempt();

    /* find a free slot in the process table */
    pcb_t *new_pcb = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            new_pcb = &pcb[i];
            break;
        }
    }
    if (new_pcb == NULL) {
        enable_preempt();
        return -1;
    }

    new_pcb->kernel_sp = allocPage(1);
    new_pcb->user_sp = allocPage(1);
    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
    new_pcb->user_stack_base = new_pcb->user_sp;
    new_pcb->preempt_count = 0;
    new_pcb->binsem_num = 0;
    new_pcb->pid = process_id++;
    new_pcb->type = task->type;
    new_pcb->status = TASK_READY;
    new_pcb->mode = mode;
    new_pcb->priority = task->priority;
    new_pcb->ready_tick = get_ticks();
    /* CPU affinity is inherited from the parent */
    new_pcb->mask = current_running[cpu_id]->mask;
    new_pcb->cursor_x = 1;
    new_pcb->cursor_y = 1;
    new_pcb->timer.list.prev = NULL;
    new_pcb->timer.list.next = NULL;
    init_list_head(&new_pcb->wait_list);

    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, task->entry_point, new_pcb, arg);
    list_add_tail(&new_pcb->list, &ready_queue);

    enable_preempt();
    return new_pcb->pid;
}

void do_exit()
{
    disable_preempt();

    pcb_t *dead = current_running[cpu_id];
    release_resources(dead);
    retire_pcb(dead);

    /* the CPU is free now, and this task will never be picked again */
    scheduler();

    enable_preempt();
}

