/* remember that `owner` holds this semaphore, so do_exit can release it */
static void take_binsem(pcb_t *owner, int binsem_id)
{
    if (owner->binsem_num < BINSEM_NUMBER) {
        owner->binsem_id[owner->binsem_num++] = binsem_id;
    }
}

/* forget a semaphore the task does not hold any more */
static void drop_binsem(pcb_t *owner, int binsem_id)
{
    for (int i = 0; i < owner->binsem_num; i++) {
        if (owner->binsem_id[i] == binsem_id) {
            owner->binsem_id[i] = owner->binsem_id[--owner->binsem_num];
            return;
        }
    }
}

/*
 * A user task always resumes in user space right after the syscall that
 * blocked it, so it cannot recheck the semaphore itself. The release side
 * therefore hands the semaphore straight over to the first waiter: being
 * woken up already means owning the semaphore.
 */
void binsem_op(int binsem_id, int op)
{
    if (binsem_id < 0 || binsem_id >= BINSEM_NUMBER) {
        return;
    }

    disable_preempt();

    binsem_node_t *node = &binsem_nodes[binsem_id];
    pcb_t *cur = current_running[cpu_id];

    if (op == BINSEM_OP_LOCK) {
        if (node->sem > 0) {
            node->sem--;
            take_binsem(cur, binsem_id);
        } else {
            do_block(&cur->list, &node->block_queue);
            scheduler();
        }
    } else if (op == BINSEM_OP_UNLOCK) {
        drop_binsem(cur, binsem_id);

        if (list_empty(&node->block_queue)) {
            node->sem = 1;
        } else {
            /* keep sem == 0: the ownership moves to the woken task */
            list_node_t *waiter = node->block_queue.next;
            take_binsem(list_entry(waiter, pcb_t, list), binsem_id);
            do_unblock(waiter);
        }
    }

    enable_preempt();
}

