int do_mbox_open(char *name)
{
    disable_preempt();

    int free_id = -1;
    for (int i = 0; i < MBOX_NUM; i++) {
        if (message_status[i]) {
            if (kstrcmp(mailbox[i].name, name) == 0) {
                /* somebody opened this mailbox before, share it */
                (message[i].opned)++;
                enable_preempt();
                return mailbox[i].id;
            }
        } else if (free_id < 0) {
            free_id = i;
        }
    }

    if (free_id < 0) {
        /* no mailbox left */
        enable_preempt();
        return -1;
    }

    message_status[free_id] = 1;
    kstrcpy(mailbox[free_id].name, name);
    mailbox[free_id].id = free_id;
    message[free_id].opned = 1;
    message[free_id].msg_len = 0;
    init_list_head(&message[free_id].wait_queue);
    if (free_id >= free_mailbox) {
        free_mailbox = free_id + 1;
    }

    enable_preempt();
    return free_id;
}

void do_mbox_close(int mailbox_id)
{
    message_t *closed_message = &message[mailbox_id];
    (closed_message->opned)--;
    if(closed_message->opned == 0){
        message_status[mailbox_id] = 0;
    }
}

/*
 * A mailbox holds a queue of bytes. Send and recv return 0 when they cannot
 * complete, after parking the caller on the mailbox: a blocked task resumes
 * in user space right after the syscall, and the user wrapper retries.
 */
int do_mbox_send(int mailbox_id, void *msg, int msg_length)
{
    if (mailbox_id < 0 || mailbox_id >= MBOX_NUM || !message_status[mailbox_id] ||
        msg_length < 0 || msg_length > MAX_MBOX_LENGTH) {
        return 0;
    }

    disable_preempt();

    message_t *box = &message[mailbox_id];

    if (box->msg_len + msg_length > MAX_MBOX_LENGTH) {
        /* the mailbox is full, wait until a receiver makes room */
        do_block(&current_running[cpu_id]->list, &box->wait_queue);
        scheduler();
        enable_preempt();
        return 0;
    }

    kmemcpy(box->msg + box->msg_len, (char *)msg, msg_length);
    box->msg_len += msg_length;

    /* a receiver may be waiting for exactly this message */
    while (!list_empty(&box->wait_queue)) {
        do_unblock(box->wait_queue.next);
    }

    enable_preempt();
    return 1;
}

int do_mbox_recv(int mailbox_id, void *msg, int msg_length)
{
    if (mailbox_id < 0 || mailbox_id >= MBOX_NUM || !message_status[mailbox_id] ||
        msg_length < 0 || msg_length > MAX_MBOX_LENGTH) {
        return 0;
    }

    disable_preempt();

    message_t *box = &message[mailbox_id];

    if (box->msg_len < msg_length) {
        /* not enough data yet, wait for a sender */
        do_block(&current_running[cpu_id]->list, &box->wait_queue);
        scheduler();
        enable_preempt();
        return 0;
    }

    kmemcpy((char *)msg, box->msg, msg_length);
    box->msg_len -= msg_length;
    /* keep the bytes nobody has read yet at the head of the queue */
    kmemcpy(box->msg, box->msg + msg_length, box->msg_len);

    /* a sender may be waiting for the space we just freed */
    while (!list_empty(&box->wait_queue)) {
        do_unblock(box->wait_queue.next);
    }

    enable_preempt();
    return 1;
}

