/*
 * Host-side unit test for the Project 3 process management, CPU affinity,
 * binary semaphores and mailbox IPC.
 *
 * The kernel sources are compiled for the host; get_ticks() is redirected to
 * host_ticks() by the test runner, and the page allocator hands out memory
 * from a real host buffer so that PCB stacks can be inspected.
 */
#include <os/sched.h>
#include <os/binsem.h>
#include <os/mailbox.h>
#include <os/smp.h>
#include <csr.h>

/* --- the clock the shimmed get_ticks() reads --- */
static uint64_t fake_ticks;
uint64_t host_ticks(void) { return fake_ticks; }

/* --- stubs for the parts of the kernel we do not want to drag in --- */
int cpu_id;
int screen_cursor_x[NR_CPUS];
int screen_cursor_y[NR_CPUS];

int printk(const char *fmt, ...) { (void)fmt; return 0; }
void vt100_move_cursor(int x, int y) { (void)x; (void)y; }
void __global_pointer$(void) {}

int preempt_depth;
void disable_preempt(void) { preempt_depth++; }
void enable_preempt(void) { preempt_depth--; }

/* a page allocator backed by real host memory, so stacks are writable */
#define HOST_PAGES 32
static char page_pool[HOST_PAGES][PAGE_SIZE] __attribute__((aligned(4096)));
static int pages_handed_out;
static ptr_t freed_page[HOST_PAGES];
static int freed_page_num;

ptr_t allocPage(int numPage)
{
    /* allocPage returns the top of the region, stacks grow down from there */
    ptr_t ret = (ptr_t)page_pool[pages_handed_out + numPage - 1] + PAGE_SIZE;
    pages_handed_out += numPage;
    return ret;
}

void freePage(ptr_t baseAddr, int numPage)
{
    for (int i = 0; i < numPage; i++) freed_page[freed_page_num++] = baseAddr;
}

static int was_freed(ptr_t addr)
{
    for (int i = 0; i < freed_page_num; i++)
        if (freed_page[i] == addr) return 1;
    return 0;
}

static char heap[65536];
static size_t heap_used;
void *kmalloc(size_t size)
{
    void *ret = &heap[heap_used];
    heap_used = (heap_used + size + 7) & ~(size_t)7;
    return ret;
}

/* --- tiny test harness --- */
extern int host_printf(const char *fmt, ...);
static int failures;

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            failures++;                                                 \
            host_printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                               \
    } while (0)

static int queue_contains(list_head *head, list_node_t *node)
{
    for (list_node_t *p = head->next; p != head; p = p->next)
        if (p == node) return 1;
    return 0;
}

/* rebuild the world the way init_pcb() in main.c does */
static void reset_world(void)
{
    fake_ticks = 1000000;
    time_base = 10000;
    timer_interval = time_base / 100;
    pages_handed_out = 0;
    freed_page_num = 0;
    heap_used = 0;
    preempt_depth = 0;
    cpu_id = 0;
    process_id = 2;

    init_list_head(&ready_queue);
    init_list_head(&sleep_queue);
    init_list_head(&timer_queue);

    for (int c = 0; c < NR_CPUS; c++) {
        kernel_pcb[c].pid = 0;
        kernel_pcb[c].type = KERNEL_PROCESS;
        kernel_pcb[c].status = TASK_RUNNING;
        kernel_pcb[c].priority = 0;
        kernel_pcb[c].mask = 1 << c;
        kernel_pcb[c].cpu_id = c;
        kernel_pcb[c].binsem_num = 0;
        kernel_pcb[c].preempt_count = 0;
        kernel_pcb[c].cursor_x = 1;
        kernel_pcb[c].cursor_y = 1;
        init_list_head(&kernel_pcb[c].wait_list);
        current_running[c] = &kernel_pcb[c];
    }
    current_cpu_running = current_running[0];

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        pcb[i].pid = -1;
        pcb[i].status = TASK_EXITED;
        pcb[i].binsem_num = 0;
        pcb[i].timer.list.prev = NULL;
        pcb[i].timer.list.next = NULL;
        pcb[i].list.prev = NULL;
        pcb[i].list.next = NULL;
    }
}

static task_info_t dummy_task = { 0x1234, USER_PROCESS, 0 };

/* pretend the given task is the one running on `core` */
static void run_on(int core, pcb_t *task)
{
    cpu_id = core;
    list_del(&task->list);
    task->status = TASK_RUNNING;
    task->cpu_id = core;
    current_running[core] = task;
    current_cpu_running = task;
}

static void test_spawn(void)
{
    reset_world();
    /* the shell is the task that spawns, it may run on either core */
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    pcb[0].status = TASK_RUNNING;
    pcb[0].binsem_num = 0;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);

    dummy_task.entry_point = 0xdeadbeef;
    pid_t pid = do_spawn(&dummy_task, (void *)0x42, ENTER_ZOMBIE_ON_EXIT);
    CHECK(pid == 2);
    pcb_t *child = &pcb[1];
    CHECK(child->pid == 2);
    CHECK(child->status == TASK_READY);
    CHECK(child->mode == ENTER_ZOMBIE_ON_EXIT);
    CHECK(child->type == USER_PROCESS);
    CHECK(child->mask == 3); /* affinity inherited from the parent */
    CHECK(child->ready_tick == fake_ticks);
    CHECK(queue_contains(&ready_queue, &child->list));
    CHECK(list_empty(&child->wait_list));
    CHECK(child->kernel_stack_base != child->user_stack_base);

    /* the prepared kernel stack must look like a trapped task */
    regs_context_t *ctx = (regs_context_t *)(child->kernel_stack_base -
                                             sizeof(regs_context_t));
    CHECK(child->kernel_sp == (reg_t)ctx);
    CHECK(ctx->regs[1] == 0xdeadbeef);                    /* ra */
    CHECK(ctx->regs[2] == (reg_t)child->user_stack_base); /* sp */
    CHECK(ctx->regs[10] == 0x42);                         /* a0 = arg */
    CHECK(ctx->sepc == 0xdeadbeef);
    CHECK(ctx->sscratch == (reg_t)child);
    CHECK((ctx->sstatus & SR_SPIE) != 0);

    /* pids keep increasing */
    CHECK(do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT) == 3);

    /* and the table can fill up */
    int spawned = 0;
    while (do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT) != -1) {
        if (++spawned > NUM_MAX_TASK) break;
    }
    CHECK(spawned <= NUM_MAX_TASK);
    CHECK(do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT) == -1);
}

static void test_affinity(void)
{
    reset_world();
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);

    /* one task pinned to core 0, one pinned to core 1 */
    pid_t p0 = do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT);
    pid_t p1 = do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT);
    CHECK(do_taskset(p0, 1) == 1);
    CHECK(do_taskset(p1, 2) == 1);
    CHECK(do_taskset(999, 3) == 0);

    /* core 1 may only pick the task whose mask contains core 1 */
    cpu_id = 1;
    CHECK(max_priority_node() == &pcb[2].list);
    scheduler();
    CHECK(current_running[1] == &pcb[2]);
    CHECK(current_running[1]->cpu_id == 1);
    CHECK(current_cpu_running == current_running[1]);

    /* core 0 may only pick the other one */
    cpu_id = 0;
    CHECK(max_priority_node() == &pcb[1].list);
    scheduler();
    CHECK(current_running[0] == &pcb[1]);

    /* nothing left for core 0: it goes idle */
    cpu_id = 0;
    current_running[0]->status = TASK_BLOCKED;
    scheduler();
    CHECK(current_running[0] == &kernel_pcb[0]);

    /* the idle task never lands in the ready queue */
    scheduler();
    CHECK(!queue_contains(&ready_queue, &kernel_pcb[0].list));
}

static void test_exit_and_wait(void)
{
    reset_world();
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    pcb[0].status = TASK_RUNNING;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);

    /* the parent spawns a child that becomes a zombie on exit */
    pid_t child_pid = do_spawn(&dummy_task, NULL, ENTER_ZOMBIE_ON_EXIT);
    pcb_t *child = &pcb[1];

    /* waiting for a task that never existed returns immediately */
    regs_context_t regs = {0};
    regs.sepc = 0x1000;
    CHECK(do_waitpid(999, 0, 0, &regs) == 0);
    CHECK(regs.sepc == 0x1000);
    CHECK(current_running[0] == &pcb[0]);

    /* waiting for a live child blocks the parent and rewinds sepc so that
     * the ecall is retried when the parent wakes up again */
    CHECK(do_waitpid(child_pid, 0, 0, &regs) == child_pid);
    CHECK(regs.sepc == 0x1000 - 4);
    CHECK(pcb[0].status == TASK_BLOCKED);
    CHECK(queue_contains(&child->wait_list, &pcb[0].list));
    CHECK(current_running[0] != &pcb[0]);

    /* the child exits: the parent is woken up */
    run_on(0, child);
    do_exit();
    CHECK(child->status == TASK_ZOMBIE);
    CHECK(pcb[0].status == TASK_READY);
    CHECK(queue_contains(&ready_queue, &pcb[0].list));
    /* a zombie keeps its stacks until it is collected */
    CHECK(!was_freed(child->kernel_stack_base));

    /* the parent retries and collects the corpse */
    run_on(0, &pcb[0]);
    regs.sepc = 0x1000;
    CHECK(do_waitpid(child_pid, 0, 0, &regs) == 1);
    CHECK(regs.sepc == 0x1000); /* no retry this time */
    CHECK(child->pid == -1);
    CHECK(child->status == TASK_EXITED);
    CHECK(was_freed(child->kernel_stack_base));
    CHECK(was_freed(child->user_stack_base));

    /* waiting again finds nothing */
    CHECK(do_waitpid(child_pid, 0, 0, &regs) == 0);

    /* a task in AUTO_CLEANUP mode is handed to core 0's idle task instead */
    pid_t auto_pid = do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT);
    pcb_t *auto_child = find_pcb_by_pid(auto_pid);
    CHECK(auto_child != NULL);
    run_on(0, auto_child);
    do_exit();
    CHECK(auto_child->status == TASK_EXITED);
    CHECK(queue_contains(&kernel_pcb[0].wait_list, &auto_child->list));
    CHECK(was_freed(auto_child->user_stack_base));
}

/* the test needs to look tasks up the same way the kernel does */
pcb_t *find_pcb_by_pid(pid_t pid)
{
    for (int i = 0; i < NUM_MAX_TASK; i++)
        if (pcb[i].pid == pid) return &pcb[i];
    return NULL;
}

static void test_kill(void)
{
    reset_world();
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    pcb[0].status = TASK_RUNNING;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);

    /* the kernel and the shell are off limits */
    CHECK(do_kill(0) == 0);
    CHECK(do_kill(1) == 0);
    CHECK(do_kill(4242) == 0);

    /* killing a ready task retires it right away */
    pid_t victim_pid = do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT);
    pcb_t *victim = find_pcb_by_pid(victim_pid);
    CHECK(do_kill(victim_pid) == 1);
    CHECK(victim->status == TASK_EXITED);
    CHECK(!queue_contains(&ready_queue, &victim->list));
    CHECK(queue_contains(&kernel_pcb[0].wait_list, &victim->list));
    CHECK(do_kill(victim_pid) == 0); /* only once */

    /* killing a task that owns the other core defers the cleanup to it */
    pid_t other_pid = do_spawn(&dummy_task, NULL, ENTER_ZOMBIE_ON_EXIT);
    pcb_t *other = find_pcb_by_pid(other_pid);
    run_on(1, other);
    cpu_id = 0;
    current_running[0] = &pcb[0];
    CHECK(do_kill(other_pid) == 1);
    CHECK(other->status == TASK_KILLED);

    /* core 1 notices on its next schedule */
    cpu_id = 1;
    scheduler();
    CHECK(other->status == TASK_ZOMBIE);
    CHECK(current_running[1] != other);

    /* a killed task wakes up whoever waits for it */
    reset_world();
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);
    pid_t child_pid = do_spawn(&dummy_task, NULL, ENTER_ZOMBIE_ON_EXIT);
    regs_context_t regs = {0};
    regs.sepc = 0x2000;
    do_waitpid(child_pid, 0, 0, &regs);
    CHECK(pcb[0].status == TASK_BLOCKED);
    cpu_id = 0;
    current_running[0] = &kernel_pcb[0];
    CHECK(do_kill(child_pid) == 1);
    CHECK(pcb[0].status == TASK_READY);
}

static void test_binsem(void)
{
    reset_world();
    init_system_binsem();
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    pcb[0].binsem_num = 0;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);

    int id = binsem_get(42);
    CHECK(binsem_get(42) == id);
    CHECK(binsem_nodes[id].sem == 1);

    /* the shell takes the semaphore and the kernel remembers that */
    binsem_op(id, BINSEM_OP_LOCK);
    CHECK(binsem_nodes[id].sem == 0);
    CHECK(pcb[0].binsem_num == 1);
    CHECK(pcb[0].binsem_id[0] == id);

    /* a second task finds it taken and blocks */
    pid_t other_pid = do_spawn(&dummy_task, NULL, AUTO_CLEANUP_ON_EXIT);
    pcb_t *other = find_pcb_by_pid(other_pid);
    run_on(0, other);
    binsem_op(id, BINSEM_OP_LOCK);
    CHECK(other->status == TASK_BLOCKED);
    CHECK(other->binsem_num == 0);
    CHECK(queue_contains(&binsem_nodes[id].block_queue, &other->list));

    /* when the owner exits, ownership is handed to the waiter */
    run_on(0, &pcb[0]);
    do_exit();
    CHECK(binsem_nodes[id].sem == 0);
    CHECK(other->status == TASK_READY);
    CHECK(other->binsem_num == 1);
    CHECK(other->binsem_id[0] == id);
    CHECK(pcb[0].binsem_num == 0);

    /* the new owner releases it for good */
    run_on(0, other);
    binsem_op(id, BINSEM_OP_UNLOCK);
    CHECK(binsem_nodes[id].sem == 1);
    CHECK(other->binsem_num == 0);

    /* a bogus id is ignored */
    binsem_op(-1, BINSEM_OP_LOCK);
    binsem_op(BINSEM_NUMBER, BINSEM_OP_LOCK);
    CHECK(binsem_nodes[id].sem == 1);
    CHECK(preempt_depth == 0);
}

static void test_mailbox(void)
{
    reset_world();
    pcb[0].pid = 1;
    pcb[0].mask = 3;
    init_list_head(&pcb[0].wait_list);
    run_on(0, &pcb[0]);
    for (int i = 0; i < MBOX_NUM; i++) message_status[i] = 0;

    int box = do_mbox_open("SunQuan-Publish-PID");
    CHECK(box >= 0);
    /* opening the same name again shares the mailbox */
    CHECK(do_mbox_open("SunQuan-Publish-PID") == box);
    CHECK(message[box].opned == 2);
    /* a different name gets its own mailbox */
    int other = do_mbox_open("LiuBei-Publish-PID");
    CHECK(other >= 0 && other != box);

    /* messages come out in the order they went in */
    int a = 0x11111111, b = 0x22222222, out = 0;
    CHECK(do_mbox_send(box, &a, sizeof(int)) == 1);
    CHECK(do_mbox_send(box, &b, sizeof(int)) == 1);
    CHECK(do_mbox_recv(box, &out, sizeof(int)) == 1);
    CHECK(out == a);
    CHECK(do_mbox_recv(box, &out, sizeof(int)) == 1);
    CHECK(out == b);

    /* receiving from an empty mailbox blocks the caller and reports failure */
    CHECK(do_mbox_recv(box, &out, sizeof(int)) == 0);
    CHECK(pcb[0].status == TASK_BLOCKED);
    CHECK(queue_contains(&message[box].wait_queue, &pcb[0].list));

    /* a send wakes the waiting receiver up */
    run_on(0, &kernel_pcb[0]);
    CHECK(do_mbox_send(box, &a, sizeof(int)) == 1);
    CHECK(pcb[0].status == TASK_READY);
    CHECK(list_empty(&message[box].wait_queue));

    /* sending more than the mailbox holds blocks the sender */
    char big[MAX_MBOX_LENGTH] = {0};
    run_on(0, &pcb[0]);
    CHECK(do_mbox_send(box, big, MAX_MBOX_LENGTH) == 0);
    CHECK(pcb[0].status == TASK_BLOCKED);

    /* draining it makes room again */
    run_on(0, &kernel_pcb[0]);
    CHECK(do_mbox_recv(box, &out, sizeof(int)) == 1);
    CHECK(out == a);
    CHECK(pcb[0].status == TASK_READY);
    CHECK(do_mbox_send(box, big, MAX_MBOX_LENGTH) == 1);

    /* a message longer than the mailbox can never be sent */
    CHECK(do_mbox_send(box, big, MAX_MBOX_LENGTH + 1) == 0);
    /* and an unknown mailbox is rejected */
    CHECK(do_mbox_send(-1, &a, sizeof(int)) == 0);
    CHECK(do_mbox_recv(MBOX_NUM, &a, sizeof(int)) == 0);

    /* closing it twice releases the slot */
    do_mbox_close(box);
    CHECK(message_status[box] == 1);
    do_mbox_close(box);
    CHECK(message_status[box] == 0);
    CHECK(preempt_depth == 0);
}

int run_tests(void)
{
    test_spawn();
    test_affinity();
    test_exit_and_wait();
    test_kill();
    test_binsem();
    test_mailbox();

    if (failures == 0)
        host_printf("p3: all process/ipc checks passed\n");
    else
        host_printf("p3: %d check(s) FAILED\n", failures);
    return failures != 0;
}

